ions":[],"ipa":null,"romanization":null,"emoji":null,"example_en":"L'ospedale è lontano.","example_es":"El hospital está lejos.","difficulty":1,"tags":["directions"]}],"lessons":[{"id":"it-a1-u10-l01","unit_id":"it-a1-u10","position":1,"title_es":"In città","objective_es":"Nombrar lugares de la ciudad.","intro":{"explanation":"Algunos lugares se parecen al español: ristorante, supermercato, stazione. Otros no: el hotel también se dice albergo, la calle es strada y el banco (de plata) es banca.","examples":[{"target":"Il ristorante è in piazza.","base":"El restaurante está en la plaza."},{"target":"Roma è una città molto bella.","base":"Roma es una ciudad muy linda."}]},"takeaways":["Nombrás lugares de la ciudad.","Sabés que el banco es banca."]},{"id":"it-a1-u10-l02","unit_id":"it-a1-u10","position":2,"title_es":"Dov'è…?","objective_es":"Preguntar dónde está un lugar.","intro":{"explanation":"Dov'è…? (dove + è) es «¿dónde está…?». A un desconocido se le habla de usted: scusi («disculpe»); a un amigo, scusa.","examples":[{"target":"Scusi, dov'è la stazione?","base":"Disculpe, ¿dónde está la estación?"},{"target":"Dov'è il supermercato?","base":"¿Dónde está el supermercado?"}]},"takeaways":["Preguntás dónde está algo con dov'è?","Le hablás de usted a un desconocido con scusi."]},{"id":"it-a1-u10-rev1","unit_id":"it-a1-u10","position":3,"title_es":"Repaso 1","objective_es":"Consolidar «In città» y «Dov'è…?».","intro":null,"takeaways":[]},{"id":"it-a1-u10-l03","unit_id":"it-a1-u10","position":4,"title_es":"Vado a… Vado in…","objective_es":"Decir adónde vas.","intro":{"explanation":"Vado es «voy» y vai «vas». Con ciudades y con casa va a: vado a Roma, vado a casa. Con lugares como banca, piazza o centro va in, sin artículo: vado in banca («voy al banco»).","examples":[{"target":"Dove vai? Vado a casa.","base":"¿Adónde vas? Voy a casa."},{"target":"Vado in banca.","base":"Voy al banco."}]},"takeaways":["Decís adónde vas con vado.","Elegís entre a (ciudades, casa) e in (lugares)."]},{"id":"it-a1-u10-l04","unit_id":"it-a1-u10","position":5,"title_es":"A destra, a sinistra","objective_es":"Entender y dar direcciones.","intro":{"explanation":"Para dar direcciones: a destra («a la derecha»), a sinistra («a la izquierda») y sempre dritto («todo derecho»). Ojo: sinistra se parece a «siniestra», que en español también quiere decir izquierda.","examples":[{"target":"La banca è a destra.","base":"El banco está a la derecha."},{"target":"Vai sempre dritto.","base":"Andá todo derecho."}]},"takeaways":["Entendés a destra y a sinistra.","Das la indicación sempre dritto."]},{"id":"it-a1-u10-rev2","unit_id":"it-a1-u10","position":6,"title_es":"Repaso 2","objective_es":"Consolidar «Vado a… Vado in…» y «A destra, a sinistra».","intro":null,"takeaways":[]},{"id":"it-a1-u10-l05","unit_id":"it-a1-u10","position":7,"title_es":"Vicino o lontano?","objective_es":"Decir si un lugar está cerca o lejos.","intro":{"explanation":"Vicino es «cerca» y lontano «lejos». Se usan con è: la stazione è vicino. Para decir cerca de qué: vicino a (vicino alla stazione).","examples":[{"target":"La stazione è vicino.","base":"La estación está cerca."},{"target":"L'ospedale è lontano?","base":"¿El hospital está lejos?"}]},"takeaways":["Decís si algo está cerca o lejos.","Preguntás y entendés indicaciones completas."]},{"id":"it-a1-u10-listen","unit_id":"it-a1-u10","position":8,"title_es":"Práctica de escucha","objective_es":"Reconocer de oído las palabras y frases de la unidad.","intro":null,"takeaways":[]},{"id":"it-a1-u10-words","unit_id":"it-a1-u10","position":9,"title_es":"Palabras de la unidad","objective_es":"Fijar el vocabulario de la unidad: reconocerlo y escribirlo.","intro":null,"takeaways":[]},{"id":"it-a1-u10-final","unit_id":"it-a1-u10","position":10,"title_es":"Repaso final","objective_es":"Demostrar todo lo de «La ciudad».","intro":null,"takeaways":[]}],"exercises":[{"id":"it-a1-u10-l01-e01","lesson_id":"it-a1-u10-l01","position":1,"type":"image_choice","skill